DROP VIEW PS_DISABLTY_ESP_VW
/
CREATE VIEW PS_DISABLTY_ESP_VW (EMPLID, DISABLED) AS SELECT A.EMPLID 
,NVL(B.DISABLED, 'N') FROM PS_PERSONAL_DATA A LEFT OUTER JOIN
 PS_DISABILITY B ON A.EMPLID = B.EMPLID
/